mapper.select:
SELECT i.id AS item_id,i.kind,v.id AS version_id,i.project_id,p.current_version_id AS project_version_id
FROM preparation_item i
JOIN preparation_version v ON v.owner_id=i.owner_id AND v.item_id=i.id AND v.id=#{versionId}
LEFT JOIN preparation_item p ON i.kind='FACT' AND p.owner_id=i.owner_id AND p.id=i.project_id AND p.kind='PROJECT'
WHERE i.owner_id=#{owner} AND i.id=#{itemId} AND i.kind=#{kind}

SELECT excerpt_id FROM preparation_material_reference
WHERE owner_id=#{owner} AND item_id=#{itemId} AND version_id=#{versionId}
ORDER BY excerpt_id LIMIT 21
